using System.IO;
using System.Windows;
using System.Windows.Controls;
using Studio.Core;
using Studio.Raple;
using TKR.Shared.resources;
namespace Studio.Desktop;
public partial class MainWindow
{
    async void DefenseActionsSmoke()=>await TryRuntime(async()=>
    {
        var output=Path.GetFullPath(".artifacts/defense-actions-desktop");Directory.CreateDirectory(output);var checks=new List<string>();await RunDefenseActionsUiSmoke(output,(passed,label)=>{if(!passed)throw new InvalidOperationException("UI check failed: "+label);checks.Add(label);});File.WriteAllText(Path.Combine(output,"ui-checks.json"),System.Text.Json.JsonSerializer.Serialize(new{checks},BehaviorDocument.JsonOptions));Application.Current.Shutdown(0);
    });
    async Task RunDefenseActionsUiSmoke(string output,Action<bool,string> check)
    {
        var previous=Snapshot();var entity=adapter.Catalog().Single(e=>e.Id=="Cave Pirate Brawler");var supplied=File.ReadAllText(entity.SourceFile);const string source="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioDefenseDesktop=()=>Behav().Init(\"Cave Pirate Brawler\",new State(\"defense\"));}}";
        ApplyProject(previous with{SourceFile=entity.SourceFile,EntityId=entity.Id,Source=source,Identities=[],SourceDrafts=[],SelectedSourceFile=null,AdditionalSources=[],LockedNodes=[],CollapsedNodes=[],Layout=[],Player=previous.Player with{Invulnerable=true}},null);SelectNode(EncounterRoot.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="ScaleHP"));check(constructorInputs["amountPerPlayer"].Text=="100"&&constructorInputs["maxAdditional"].Text=="0"&&createNativeButton!.IsEnabled,"Native additive HP creation exposes typed HP amount and no-cap starting inputs");constructorInputs["scaleAfter"].Text="0";createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var hp=selectedNode!;check(scalingPanel is{IsExpanded:false},"Native scaling details stay collapsed beside exact source parameters");
        SelectNode(EncounterRoot.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="ScaleDefense"));check(constructorInputs["perPerson"].Text=="5"&&createNativeButton!.IsEnabled,"Native defense creation uses the original perPerson constructor");createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var defense=selectedNode!;
        check(await StartSessionAsync(),"Play runs the accepted additive HP and defense source");running=false;await session!.AdvanceAsync(new(),100);UpdateSession();var descriptor=EntityResources.Catalog(EntityResourceScope.Enemy).Single(e=>e.Id==entity.Id);check(session.Entities.Single().MaxHp==descriptor.MaxHp+100&&session.Entities.Single().Defense==descriptor.Defense+5,"Desktop native actor snapshots retain scaled max HP and overwritten defense");Stop(this,new());
        SelectNode(EncounterRoot.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="RemoveConditionalEffect"));createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var removal=selectedNode!;check(conditionActionPanel is{IsExpanded:false}&&conditionActionChoice?.SelectedItem is ConditionEffectIndex.Invulnerable,"Removal exposes a quiet typed picker for actual native condition values");var before=document.Source;var revision=document.Revision;conditionActionPanel!.IsExpanded=true;conditionActionChoice!.SelectedItem=ConditionEffectIndex.Armored;conditionActionUse!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(document.Revision==revision+1&&adapter.ReadConditionAction(document,document.Find(removal.Id))==ConditionEffectIndex.Armored,"Actual condition picker commits one typed native enum edit");Undo(this,new());check(document.Source==before&&document.Find(removal.Id).Id==removal.Id,"Condition Undo restores exact source and action identity");Redo(this,new());SelectNode(removal.Id);Inspector.Children.OfType<CheckBox>().Single().IsChecked=true;check(conditionActionChoice?.IsEnabled==false&&conditionActionUse?.IsEnabled==false,"Region lock disables the native condition chooser and Apply");document.LockedNodes.Clear();SelectNode(removal.Id);var accepted=document.Source;var stale=false;try{adapter.ApplyConditionAction(document,entity.Id,removal.Id,document.Revision-1,ConditionEffectIndex.Weak);}catch(InvalidOperationException){stale=true;}check(stale&&document.Source==accepted,"Stale host-condition edits preserve accepted source");
        SelectNode(EncounterRoot.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="ScaleHP2"));check(constructorInputs["amount"].Text=="10"&&createNativeButton!.IsEnabled,"Native percentage scaling creation exposes the original XML-percent amount");createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var percent=selectedNode!;scalingPanel!.IsExpanded=true;WorkspaceTabs.SelectedIndex=1;UpdateLayout();CaptureView(this,Path.Combine(output,"native-scaling.png"));check(RapleAdapter.ScalingWeaponInfo(selectedWeaponId)!=null&&scalingPanel!=null,"Percentage inspector resolves actual selected weapon gear flags while identifying empty prototype slots");
        var saved=Path.Combine(output,"defense.rbs");BehaviorDocument.Save(saved,Snapshot());ApplyProject(BehaviorDocument.Load(saved),saved);check(new[]{hp.Id,defense.Id,removal.Id,percent.Id}.All(id=>document.Find(id).Id==id)&&adapter.ReadConditionAction(document,document.Find(removal.Id))==ConditionEffectIndex.Armored,"Save/reopen retains all native defense actions and exact condition source");check(await StartSessionAsync(),"Play runs the reopened combined native defense source");running=false;await session!.AdvanceAsync(new(),100);UpdateSession();var gear=RapleAdapter.ScalingWeaponInfo(selectedWeaponId)!;check(session.Entities.Single().MaxHp==descriptor.MaxHp+100+10*descriptor.MaxHp/100+gear.NativeGearPoints*descriptor.MaxHp/40,"Native percentage scaling uses XML max HP after the earlier source-order additive action");Stop(this,new());
        SelectNode(EncounterRoot.Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="TransferDamageOnDeath"));constructorInputs["target"].Text="\"Big Yeti\"";createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(adapter.EntityParameterFor(document,selectedNode!)?.Label=="Damage-record recipient"&&entityPicker!=null,"Death record transfer exposes the native Enemy recipient XML picker");check(adapter.Callbacks("TransferDamageOnDeath").Single().Stage=="Death","Lifecycle view retains transfer at actual native death rather than a relocated stage");
        check(File.ReadAllText(entity.SourceFile)==supplied,"Defense UI, history and native playback preserve supplied game source");ApplyProject(previous,null);WorkspaceTabs.SelectedIndex=0;
    }
}
